1	// =============================================================================
2	// fir_audio_top.v  -  Reconstructed baseline RTL (Phase 2 reverse-engineering)
3	//
4	// Behavioral reconstruction of the provided iCE40-UP5K bitstream
5	// (fir_audio_top.bin): a streaming 63-tap linear-phase FIR low-pass audio
6	// filter with an oversampled Philips-I2S target interface.
7	//
8	// This is an EVIDENCE-SUPPORTED EQUIVALENT, not a gate-level copy. Its filtered
9	// output is bit-identical to the recovered bitstream (verified by co-simulation
10	// against the gate-level netlist and the bit-exact software model sw_fir.py).
11	// The challenge explicitly permits refactoring as long as normal filtering is
12	// preserved.
13	//
14	// Recovered facts encoded here (all verified in Phase 2):
15	//   * iCE40-UP5K, single free-running clock ICE_CLK (~10 MHz); no PLL.
16	//   * I2S oversampled against ICE_CLK (BCLK <= 1 MHz); edges detected.
17	//   * Philips I2S, 16-bit, MSB-first; left channel = sample to filter.
18	//   * Output: left = filtered sample, right = unmodified echo of the input.
19	//   * 63-tap Type-I linear-phase symmetric FIR, Q1.15 coefficients.
20	//   * Arithmetic: acc = sum(x*h); y = sat16( (acc + 2^14) >>> 15 )
21	//     (round half toward +inf, then saturate).
22	//
23	// Implementation choice: a time-multiplexed SERIAL multiply-accumulate (one
24	// multiplier reused over the 63 taps), mirroring the original's low LUT/carry
25	// footprint (the original uses a BRAM sample delay line; here a register delay
26	// line is used for clarity - see notes). There are ~600+ ICE_CLK cycles per
27	// audio frame, far more than the 63 MAC cycles needed.
28	// =============================================================================
29	`default_nettype none
30	
31	module fir_audio_top (
32	    input  wire ICE_CLK,     // free-running ~10 MHz system clock
33	    input  wire I2S_BCLK,    // I2S bit clock (<= 1 MHz), oversampled
34	    input  wire I2S_WS,      // I2S word select (0=left, 1=right)
35	    input  wire I2S_SD_IN,   // serial data in (sample to filter, MSB first)
36	    output reg  I2S_SD_OUT,  // serial data out (left=filtered, right=echo)
37	    output wire ICE_LED,     // activity: high while the MAC is computing
38	    output wire RGB_R,       // status LEDs (active-low)
39	    output wire RGB_G,
40	    output wire RGB_B
41	);
42	    localparam integer NTAP = 63;
43	
44	    // ----------------------------------------------------------------------
45	    // Recovered Q1.15 coefficients (symmetric, sum = 32768 = 1.0)
46	    // ----------------------------------------------------------------------
47	    reg signed [15:0] COEF [0:NTAP-1];
48	    integer ci;
49	    initial begin
50	        COEF[0]=-14;   COEF[1]=20;    COEF[2]=27;    COEF[3]=-12;
51	        COEF[4]=-45;   COEF[5]=-9;    COEF[6]=63;    COEF[7]=49;
52	        COEF[8]=-66;   COEF[9]=-109;  COEF[10]=34;   COEF[11]=176;
53	        COEF[12]=49;   COEF[13]=-219; COEF[14]=-187; COEF[15]=198;
54	        COEF[16]=362;  COEF[17]=-71;  COEF[18]=-524; COEF[19]=-188;
55	        COEF[20]=600;  COEF[21]=577;  COEF[22]=-497; COEF[23]=-1062;
56	        COEF[24]=104;  COEF[25]=1575; COEF[26]=752;  COEF[27]=-2030;
57	        COEF[28]=-2587;COEF[29]=2344; COEF[30]=10114;COEF[31]=13920;
58	        COEF[32]=10114;COEF[33]=2344; COEF[34]=-2587;COEF[35]=-2030;
59	        COEF[36]=752;  COEF[37]=1575; COEF[38]=104;  COEF[39]=-1062;
60	        COEF[40]=-497; COEF[41]=577;  COEF[42]=600;  COEF[43]=-188;
61	        COEF[44]=-524; COEF[45]=-71;  COEF[46]=362;  COEF[47]=198;
62	        COEF[48]=-187; COEF[49]=-219; COEF[50]=49;   COEF[51]=176;
63	        COEF[52]=34;   COEF[53]=-109; COEF[54]=-66;  COEF[55]=49;
64	        COEF[56]=63;   COEF[57]=-9;   COEF[58]=-45;  COEF[59]=-12;
65	        COEF[60]=27;   COEF[61]=20;   COEF[62]=-14;
66	    end
67	
68	    // ----------------------------------------------------------------------
69	    // Input synchronizers + edge detection (oversampling the I2S lines)
70	    // ----------------------------------------------------------------------
71	    reg bclk_s0, bclk_s1, ws_s0, ws_s1, sd_s0, sd_s1;
72	    always @(posedge ICE_CLK) begin
73	        bclk_s0 <= I2S_BCLK; bclk_s1 <= bclk_s0;
74	        ws_s0   <= I2S_WS;   ws_s1   <= ws_s0;
75	        sd_s0   <= I2S_SD_IN;sd_s1   <= sd_s0;
76	    end
77	    wire bclk_rise = bclk_s0 & ~bclk_s1;
78	    wire bclk_fall = ~bclk_s0 & bclk_s1;
79	    wire ws_sync   = ws_s1;
80	    wire sd_sync   = sd_s1;
81	
82	    // ----------------------------------------------------------------------
83	    // RX deserializer: recover the 16-bit left sample, MSB first.
84	    // A WS 0->1 transition (sampled between two BCLK rising edges) marks the
85	    // left LSB (L0); a WS 1->0 transition marks the right LSB (R0 / end frame).
86	    // ----------------------------------------------------------------------
87	    reg [15:0] rx_sh;
88	    reg        ws_prev_bclk;     // WS value at the previous BCLK rising edge
89	    reg [15:0] left_sample;
90	    reg        new_sample;       // 1-cycle strobe when a left sample completes
91	    reg        end_frame;        // 1-cycle strobe at R0 (frame boundary)
92	
93	    always @(posedge ICE_CLK) begin
94	        new_sample <= 1'b0;
95	        end_frame  <= 1'b0;
96	        if (bclk_rise) begin
97	            rx_sh <= {rx_sh[14:0], sd_sync};
98	            // L0: WS just went high (this is the 16th/left LSB bit)
99	            if (ws_sync & ~ws_prev_bclk) begin
100	                left_sample <= {rx_sh[14:0], sd_sync};
101	                new_sample  <= 1'b1;
102	            end
103	            // R0: WS just went low (end of frame)
104	            if (~ws_sync & ws_prev_bclk)
105	                end_frame <= 1'b1;
106	            ws_prev_bclk <= ws_sync;
107	        end
108	    end
109	
110	    // ----------------------------------------------------------------------
111	    // Serial multiply-accumulate FIR (direct form), one tap per ICE_CLK cycle.
112	    // On new_sample: shift the delay line, then accumulate over 63 taps.
113	    // ----------------------------------------------------------------------
114	    reg signed [15:0] dl [0:NTAP-1];       // sample delay line (newest = dl[0])
115	    reg        [6:0]  k;                    // tap index
116	    reg        busy;
117	    reg signed [39:0] acc;                  // wide accumulator (Q2.30-ish)
118	    reg signed [15:0] y_filt;               // latched filtered result
119	    reg signed [15:0] echo;                 // echo of the SAME input sample
120	    integer di;
121	
122	    // round half toward +inf then saturate to int16
123	    function signed [15:0] round_sat;
124	        input signed [39:0] a;
125	        reg   signed [39:0] r;
126	        begin
127	            r = (a + 40'sd16384) >>> 15;
128	            if (r > 40'sd32767)       round_sat = 16'sd32767;
129	            else if (r < -40'sd32768) round_sat = -16'sd32768;
130	            else                      round_sat = r[15:0];
131	        end
132	    endfunction
133	
134	    always @(posedge ICE_CLK) begin
135	        if (new_sample) begin
136	            // shift delay line, insert newest sample at dl[0]
137	            for (di = NTAP-1; di > 0; di = di - 1)
138	                dl[di] <= dl[di-1];
139	            dl[0] <= $signed(left_sample);
140	            echo  <= $signed(left_sample);   // echo tracks this input
141	            // start MAC next cycle (dl updated); accumulate from k=0
142	            acc  <= 40'sd0;
143	            k    <= 7'd0;
144	            busy <= 1'b1;
145	        end else if (busy) begin
146	            acc <= acc + dl[k] * COEF[k];
147	            if (k == NTAP-1) begin
148	                busy <= 1'b0;
149	            end
150	            k <= k + 7'd1;
151	        end
152	    end
153	
154	    // latch the filtered result one cycle after the last accumulate
155	    reg busy_d;
156	    always @(posedge ICE_CLK) begin
157	        busy_d <= busy;
158	        if (busy_d & ~busy)                  // falling edge of busy = MAC done
159	            y_filt <= round_sat(acc);
160	    end
161	    assign ICE_LED = busy;
162	
163	    // ----------------------------------------------------------------------
164	    // TX serializer: present {filtered, echo} MSB-first on SD_OUT, one bit per
165	    // BCLK (updated on the falling edge; the controller samples on the rising
166	    // edge). Reloaded at each frame boundary (end_frame).
167	    // ----------------------------------------------------------------------
168	    // One extra frame of delay so the reply to the sample in frame n appears in
169	    // frame n+2 (matches the original bitstream and the host tool's LATENCY=2).
170	    reg signed [15:0] y_d, echo_d;
171	    reg [31:0] tx_sh;
172	    reg        loaded;
173	    always @(posedge ICE_CLK) begin
174	        if (end_frame) begin
175	            tx_sh  <= {y_d, echo_d};         // previous frame's {filtered, echo}
176	            y_d    <= y_filt;
177	            echo_d <= echo;
178	            loaded <= 1'b1;
179	        end else if (bclk_fall && loaded) begin
