70	    // ----------------------------------------------------------------------
71	    reg bclk_s0, bclk_s1, ws_s0, ws_s1, sd_s0, sd_s1;
72	    always @(posedge ICE_CLK) begin
73	        bclk_s0 <= I2S_BCLK; bclk_s1 <= bclk_s0;
74	        ws_s0   <= I2S_WS;   ws_s1   <= ws_s0;
75	        sd_s0   <= I2S_SD_IN;sd_s1   <= sd_s0;
76	    end
77	    wire bclk_rise = bclk_s0 & ~bclk_s1;
78	    wire bclk_fall = ~bclk_s0 & bclk_s1;
79	    wire ws_sync   = ws_s1;
80	    wire sd_sync   = sd_s1;
81	
82	    // ----------------------------------------------------------------------
83	    // RX deserializer: recover the 16-bit left sample, MSB first.
84	    // A WS 0->1 transition (sampled between two BCLK rising edges) marks the
85	    // left LSB (L0); a WS 1->0 transition marks the right LSB (R0 / end frame).
86	    // ----------------------------------------------------------------------
87	    reg [15:0] rx_sh;
88	    reg        ws_prev_bclk;     // WS value at the previous BCLK rising edge
89	    reg [15:0] left_sample;
90	    reg        new_sample;       // 1-cycle strobe when a left sample completes
91	    reg        end_frame;        // 1-cycle strobe at R0 (frame boundary)
92	
93	    always @(posedge ICE_CLK) begin
94	        new_sample <= 1'b0;
95	        end_frame  <= 1'b0;
96	        if (bclk_rise) begin
97	            rx_sh <= {rx_sh[14:0], sd_sync};
98	            // L0: WS just went high (this is the 16th/left LSB bit)
99	            if (ws_sync & ~ws_prev_bclk) begin
100	                left_sample <= {rx_sh[14:0], sd_sync};
101	                new_sample  <= 1'b1;
102	            end
103	            // R0: WS just went low (end of frame)
104	            if (~ws_sync & ws_prev_bclk)
105	                end_frame <= 1'b1;
106	            ws_prev_bclk <= ws_sync;
107	        end
108	    end
109	
110	    // ----------------------------------------------------------------------
111	    // Serial multiply-accumulate FIR (direct form), one tap per ICE_CLK cycle.
112	    // On new_sample: shift the delay line, then accumulate over 63 taps.
113	    // ----------------------------------------------------------------------
114	    reg signed [15:0] dl [0:NTAP-1];       // sample delay line (newest = dl[0])
115	    reg        [6:0]  k;                    // tap index
116	    reg        busy;
117	    reg signed [39:0] acc;                  // wide accumulator (Q2.30-ish)
118	    reg signed [15:0] y_filt;               // latched filtered result
119	    reg signed [15:0] echo;                 // echo of the SAME input sample
120	    integer di;
121	
122	    // round half toward +inf then saturate to int16
123	    function signed [15:0] round_sat;
124	        input signed [39:0] a;
125	        reg   signed [39:0] r;
126	        begin
127	            r = (a + 40'sd16384) >>> 15;
128	            if (r > 40'sd32767)       round_sat = 16'sd32767;
129	            else if (r < -40'sd32768) round_sat = -16'sd32768;
130	            else                      round_sat = r[15:0];
131	        end
132	    endfunction
133	
134	    always @(posedge ICE_CLK) begin
135	        if (new_sample) begin
136	            // shift delay line, insert newest sample at dl[0]
137	            for (di = NTAP-1; di > 0; di = di - 1)
138	                dl[di] <= dl[di-1];
139	            dl[0] <= $signed(left_sample);
140	            echo  <= $signed(left_sample);   // echo tracks this input
141	            // start MAC next cycle (dl updated); accumulate from k=0
142	            acc  <= 40'sd0;
143	            k    <= 7'd0;
144	            busy <= 1'b1;
145	        end else if (busy) begin
146	            acc <= acc + dl[k] * COEF[k];
147	            if (k == NTAP-1) begin
148	                busy <= 1'b0;
149	            end
150	            k <= k + 7'd1;
151	        end
152	    end
153	
154	    // latch the filtered result one cycle after the last accumulate
155	    reg busy_d;
156	    always @(posedge ICE_CLK) begin
157	        busy_d <= busy;
158	        if (busy_d & ~busy)                  // falling edge of busy = MAC done
159	            y_filt <= round_sat(acc);
160	    end
161	    assign ICE_LED = busy;
162	
163	    // ----------------------------------------------------------------------
164	    // TX serializer: present {filtered, echo} MSB-first on SD_OUT, one bit per
165	    // BCLK (updated on the falling edge; the controller samples on the rising
166	    // edge). Reloaded at each frame boundary (end_frame).
167	    // ----------------------------------------------------------------------
168	    // One extra frame of delay so the reply to the sample in frame n appears in
169	    // frame n+2 (matches the original bitstream and the host tool's LATENCY=2).
170	    reg signed [15:0] y_d, echo_d;
171	    reg [31:0] tx_sh;
172	    reg        loaded;
173	    always @(posedge ICE_CLK) begin
174	        if (end_frame) begin
175	            tx_sh  <= {y_d, echo_d};         // previous frame's {filtered, echo}
176	            y_d    <= y_filt;
177	            echo_d <= echo;
178	            loaded <= 1'b1;
179	        end else if (bclk_fall && loaded) begin
180	            I2S_SD_OUT <= tx_sh[31];
181	            tx_sh      <= {tx_sh[30:0], 1'b0};
182	        end
183	    end
184	
185	    // Status LEDs (active-low): green while streaming (frames seen), blue idle.
186	    assign RGB_G = ~loaded;      // low (on) once streaming
187	    assign RGB_B = loaded;       // high (off) once streaming
188	    assign RGB_R = 1'b1;         // overrun indicator (active-low): never asserts here
189	
190	    // Power-up state (iCE40 FFs power up to 0); placed after all declarations.
191	    integer pi;
192	    initial begin
193	        I2S_SD_OUT = 1'b0; busy = 1'b0; busy_d = 1'b0; loaded = 1'b0;
194	        new_sample = 1'b0; end_frame = 1'b0; ws_prev_bclk = 1'b0;
195	        k = 7'd0; acc = 40'sd0; rx_sh = 16'd0; tx_sh = 32'd0;
196	        left_sample = 16'd0; y_filt = 16'd0; echo = 16'd0;
197	        y_d = 16'd0; echo_d = 16'd0;
198	        for (pi = 0; pi < NTAP; pi = pi + 1) dl[pi] = 16'sd0;
199	    end
200	
201	endmodule
202	`default_nettype wire
